type Result =
  | { ok: true; data: string }
  | { ok: false; error: Error };

function read(result: Result) {
  if (result.ok) return result.data;
  return result.error.message;
}

function print(value: unknown) {
  if (typeof value === "string") {
    return value.toUpperCase();
  }
}

